-- Feature 21: append-only, local fixture evidence only. No product permission state.
CREATE TABLE IF NOT EXISTS usage_rights_scopes (operator_test_id text NOT NULL, scope_hash char(64) NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS usage_rights_feature03_contexts (operator_test_id text NOT NULL, scope_hash char(64) NOT NULL, run_id text NOT NULL, artifact_hash char(64) NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(operator_test_id,scope_hash,run_id), UNIQUE(operator_test_id,scope_hash,artifact_hash), FOREIGN KEY(operator_test_id,scope_hash) REFERENCES usage_rights_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS usage_rights_rulepacks (operator_test_id text NOT NULL, scope_hash char(64) NOT NULL, rulepack_id text NOT NULL, revision integer NOT NULL CHECK(revision>0), artifact_hash char(64) NOT NULL, predecessor_hash char(64), payload jsonb NOT NULL, PRIMARY KEY(operator_test_id,scope_hash,rulepack_id,revision), UNIQUE(operator_test_id,scope_hash,artifact_hash), FOREIGN KEY(operator_test_id,scope_hash) REFERENCES usage_rights_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS usage_rights_sources (operator_test_id text NOT NULL, scope_hash char(64) NOT NULL, source_id text NOT NULL, revision integer NOT NULL CHECK(revision>0), artifact_hash char(64) NOT NULL, predecessor_hash char(64), payload jsonb NOT NULL, PRIMARY KEY(operator_test_id,scope_hash,source_id,revision), UNIQUE(operator_test_id,scope_hash,artifact_hash), FOREIGN KEY(operator_test_id,scope_hash) REFERENCES usage_rights_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS usage_rights_artifacts (operator_test_id text NOT NULL, scope_hash char(64) NOT NULL, artifact_kind text NOT NULL, artifact_hash char(64) NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(operator_test_id,scope_hash,artifact_kind,artifact_hash), FOREIGN KEY(operator_test_id,scope_hash) REFERENCES usage_rights_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS usage_rights_decisions (operator_test_id text NOT NULL, scope_hash char(64) NOT NULL, decision_hash char(64) NOT NULL, request_hash char(64) NOT NULL, predecessor_hash char(64), expires_at timestamptz NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(operator_test_id,scope_hash,decision_hash), UNIQUE(operator_test_id,scope_hash,request_hash,predecessor_hash), FOREIGN KEY(operator_test_id,scope_hash) REFERENCES usage_rights_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS usage_rights_obligation_receipts (operator_test_id text NOT NULL, scope_hash char(64) NOT NULL, decision_hash char(64) NOT NULL, obligation text NOT NULL, receipt_hash char(64) NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(operator_test_id,scope_hash,decision_hash,obligation), UNIQUE(operator_test_id,scope_hash,receipt_hash), FOREIGN KEY(operator_test_id,scope_hash,decision_hash) REFERENCES usage_rights_decisions(operator_test_id,scope_hash,decision_hash));
CREATE TABLE IF NOT EXISTS usage_rights_request_claims (operator_test_id text NOT NULL, idempotency_key text NOT NULL, request_hash char(64) NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(operator_test_id,idempotency_key));
CREATE TABLE IF NOT EXISTS usage_rights_conflicts (operator_test_id text NOT NULL, idempotency_key text NOT NULL, request_hash char(64) NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(operator_test_id,idempotency_key,request_hash));
CREATE TABLE IF NOT EXISTS usage_rights_operation_requests (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,request_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,request_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES usage_rights_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS usage_rights_leaf_matches (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,decision_hash char(64) NOT NULL,leaf_id text NOT NULL,assertion_hash char(64),payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,decision_hash,leaf_id),FOREIGN KEY(operator_test_id,scope_hash,decision_hash) REFERENCES usage_rights_decisions(operator_test_id,scope_hash,decision_hash));
CREATE TABLE IF NOT EXISTS usage_rights_obligation_requirements (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,decision_hash char(64) NOT NULL,obligation text NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,decision_hash,obligation),FOREIGN KEY(operator_test_id,scope_hash,decision_hash) REFERENCES usage_rights_decisions(operator_test_id,scope_hash,decision_hash));
CREATE TABLE IF NOT EXISTS usage_rights_test_center_bundles (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,decision_hash char(64) NOT NULL,run_id text NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,decision_hash),FOREIGN KEY(operator_test_id,scope_hash,decision_hash) REFERENCES usage_rights_decisions(operator_test_id,scope_hash,decision_hash));
CREATE TABLE IF NOT EXISTS usage_rights_source_heads (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,source_id text NOT NULL,head_hash char(64) NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,source_id),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES usage_rights_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS usage_rights_owner_attestations (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES usage_rights_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS usage_rights_assertions (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,rulepack_hash char(64) NOT NULL,assertion_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,rulepack_hash,assertion_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES usage_rights_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS usage_rights_golden_manifests (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES usage_rights_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS usage_rights_golden_case_receipts (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,manifest_hash char(64) NOT NULL,case_id text NOT NULL,receipt_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,manifest_hash,case_id),UNIQUE(operator_test_id,scope_hash,receipt_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES usage_rights_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS usage_rights_rulepack_changes (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES usage_rights_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS usage_rights_activation_receipts (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,sequence integer NOT NULL CHECK(sequence>0),artifact_hash char(64) NOT NULL,predecessor_hash char(64),payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,sequence),UNIQUE(operator_test_id,scope_hash,artifact_hash),CHECK((sequence=1 AND predecessor_hash IS NULL) OR (sequence>1 AND predecessor_hash IS NOT NULL)),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES usage_rights_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS usage_rights_subjects (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,subject_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,subject_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES usage_rights_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS usage_rights_lineage_nodes (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,subject_hash char(64) NOT NULL,node_id text NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,subject_hash,node_id),FOREIGN KEY(operator_test_id,scope_hash,subject_hash) REFERENCES usage_rights_subjects(operator_test_id,scope_hash,subject_hash));
CREATE TABLE IF NOT EXISTS usage_rights_lineage_edges (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,subject_hash char(64) NOT NULL,parent_id text NOT NULL,child_id text NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,subject_hash,parent_id,child_id),CHECK(parent_id<>child_id),FOREIGN KEY(operator_test_id,scope_hash,subject_hash,parent_id) REFERENCES usage_rights_lineage_nodes(operator_test_id,scope_hash,subject_hash,node_id),FOREIGN KEY(operator_test_id,scope_hash,subject_hash,child_id) REFERENCES usage_rights_lineage_nodes(operator_test_id,scope_hash,subject_hash,node_id));
CREATE TABLE IF NOT EXISTS usage_rights_lifecycle_transitions (operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,transition_hash char(64) NOT NULL,predecessor_hash char(64),payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,transition_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES usage_rights_scopes(operator_test_id,scope_hash));
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='usage_rights_decision_request_fk' AND conrelid='usage_rights_decisions'::regclass) THEN
    ALTER TABLE usage_rights_decisions ADD CONSTRAINT usage_rights_decision_request_fk FOREIGN KEY(operator_test_id,scope_hash,request_hash) REFERENCES usage_rights_operation_requests(operator_test_id,scope_hash,request_hash);
  END IF;
END $$;
CREATE OR REPLACE FUNCTION usage_rights_append_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'usage_rights_append_only'; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['usage_rights_scopes','usage_rights_feature03_contexts','usage_rights_rulepacks','usage_rights_sources','usage_rights_artifacts','usage_rights_decisions','usage_rights_obligation_receipts','usage_rights_request_claims','usage_rights_conflicts','usage_rights_operation_requests','usage_rights_leaf_matches','usage_rights_obligation_requirements','usage_rights_test_center_bundles','usage_rights_source_heads','usage_rights_owner_attestations','usage_rights_assertions','usage_rights_golden_manifests','usage_rights_golden_case_receipts','usage_rights_rulepack_changes','usage_rights_activation_receipts','usage_rights_subjects','usage_rights_lineage_nodes','usage_rights_lineage_edges','usage_rights_lifecycle_transitions'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS usage_rights_no_mutation ON %I',t); EXECUTE format('CREATE TRIGGER usage_rights_no_mutation BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION usage_rights_append_only()',t); END LOOP; END $$;
CREATE OR REPLACE VIEW usage_rights_current_fixture_projection AS SELECT operator_test_id,scope_hash,count(*) AS decision_count,array_agg(DISTINCT payload->>'disposition') AS dispositions FROM usage_rights_decisions GROUP BY operator_test_id,scope_hash;
